__all__ = ["SymbolicReference"]

import os
from pathlib import Path

from gitdb.exc import BadName, BadObject
from git.compat import defenc
from git.objects.commit import Commit
from git.refs.log import RefLog
from git.util import (
    LockedFD,
    assure_directory_exists,
    hex_to_bin,
    join_path,
    join_path_native,
    to_native_path_linux,
)

from typing import (
    Any,
    Iterator,
    List,
    TYPE_CHECKING,
    Tuple,
    Type,
    TypeVar,
    Union,
    cast,
)

from git.types import AnyGitObject, PathLike

if TYPE_CHECKING:
    from git.config import GitConfigParser
    from git.objects.commit import Actor
    from git.refs.log import RefLogEntry
    from git.refs.reference import Reference
    from git.repo import Repo

T_References = TypeVar("T_References", bound="SymbolicReference")


def _git_dir(repo: "Repo", path: Union[PathLike, None]) -> PathLike:
    """Find the git dir that is appropriate for the path."""
    name = f"{path}"
    if name in ["HEAD", "ORIG_HEAD", "FETCH_HEAD", "index", "logs"]:
        return repo.git_dir
    return repo.common_dir


class SymbolicReference:
    """Special case of a reference that is symbolic.

    This does not point to a specific commit, but to another
    :class:`~git.refs.head.Head`, which itself specifies a commit.

    A typical example for a symbolic reference is :class:`~git.refs.head.HEAD`.
    """

    __slots__ = ("repo", "path")

    _resolve_ref_on_create = False
    _points_to_commits_only = True
    _common_path_default = ""
    _remote_common_path_default = "refs/remotes"
    _id_attribute_ = "name"

    def __init__(self, repo: "Repo", path: PathLike, check_path: bool = False) -> None:
        """
        :param repo: Repository object
        :param path: Path to the reference
        :param check_path: Whether to check the reference path for validity
        """
        self.repo = repo
        self.path: PathLike = path

    @property
    def abspath(self) -> PathLike:
        """
        :return: Absolute path to the reference
        """
        return join_path_native(_git_dir(self.repo, self.path), self.path)

    @classmethod
    def _get_packed_refs_path(cls, repo: "Repo") -> str:
        """
        :param repo: Repository object
        :return: Path to the packed refs file
        """
        return os.path.join(repo.common_dir, "packed-refs")

    @classmethod
    def _iter_packed_refs(cls, repo: "Repo") -> Iterator[Tuple[str, str]]:
        """Return an iterator yielding pairs of sha1/path pairs (as strings) for the
        corresponding refs.
        """
        try:
            with open(cls._get_packed_refs_path(repo), "rt", encoding="UTF-8") as fp:
                for line in fp:
                    line = line.strip()
                    if not line or line.startswith("#") or line[0] == "^":
                        continue
                    yield cast(Tuple[str, str], tuple(line.split(" ", 1)))
        except OSError:
            return iter(())

    @staticmethod
    def _check_ref_name_valid(ref_path: PathLike) -> None:
        """Check a ref name for validity."""
        ref = os.fspath(ref_path)
        if ref in ["", ".", "/"]:
            raise ValueError(f"Invalid reference '{ref_path}': cannot be empty or start with /, .")
        if ".." in ref:
            raise ValueError(f"Invalid reference '{ref_path}': cannot contain '..'")
        if any(c in " ~^:?*[\\" for c in ref):
            raise ValueError(f"Invalid reference '{ref_path}': cannot contain space, ~, ^, :, ?, *, [, \\")
        if any(c < 32 or c == 127 for c in ref):
            raise ValueError(f"Invalid reference '{ref_path}': cannot contain control characters")
        if ref.endswith(".lock"):
            raise ValueError(f"Invalid reference '{ref_path}': cannot end with '.lock'")

    @classmethod
    def _get_ref_info(cls, repo: "Repo", ref_path: Union[PathLike, None]) -> Union[Tuple[str, None], Tuple[None, str]]:
        """
        :return: (sha, target_ref_path) tuple
        """
        if ref_path:
            cls._check_ref_name_valid(ref_path)

        tokens = None
        repodir = _git_dir(repo, ref_path)
        try:
            with open(os.path.join(repodir, ref_path), "rt", encoding="UTF-8") as fp:
                value = fp.read().rstrip().split(None, 1)
                if len(value) != 0:
                    tokens = value
        except OSError:
            for sha, path in cls._iter_packed_refs(repo):
                if path == ref_path:
                    tokens = sha, path
                    break
        if tokens is None:
            raise ValueError(f"Reference at {ref_path} does not exist")

        if tokens[0] == "ref:":
            return (None, tokens[1])
        if repo.re_hexsha_only.match(tokens[0]):
            return (tokens[0], None)
        raise ValueError(f"Failed to parse reference information from {ref_path}")

    def _get_reference(self) -> "Reference":
        """
        :return: Reference object we point to
        :raise TypeError: If this symbolic reference is detached
        """
        sha, target_ref_path = self._get_ref_info(self.repo, self.path)
        if target_ref_path is None:
            raise TypeError(f"{self} is a detached symbolic reference as it points to {sha}")
        return cast("Reference", self.from_path(self.repo, target_ref_path))

    def set_reference(
        self,
        ref: Union[AnyGitObject, "SymbolicReference", str],
        logmsg: Union[str, None] = None,
    ) -> "SymbolicReference":
        """Set ourselves to the given `ref`.

        :param ref: SymbolicReference, Object, or refspec string
        :param logmsg: Message for reflog or None
        :return: self
        """
        write_value = None
        obj = None
        if isinstance(ref, SymbolicReference):
            write_value = f"ref: {ref.path}"
        elif isinstance(ref, Object):
            obj = ref
        elif isinstance(ref, str):
            obj = self.repo.rev_parse(ref + "^{}")
        else:
            raise ValueError(f"Unrecognized Value: {ref}")

        if obj is not None and self._points_to_commits_only and obj.type != Commit.type:
            raise TypeError(f"Require commit, got {obj}")

        oldbinsha = b""
        if logmsg is not None:
            try:
                oldbinsha = self.commit.binsha
            except ValueError:
                oldbinsha = Commit.NULL_BIN_SHA

        fpath = self.abspath
        assure_directory_exists(fpath, is_file=True)

        lfd = LockedFD(fpath)
        fd = lfd.open(write=True, stream=True)
        try:
            fd.write(write_value.encode("utf-8") + b"\n")
            lfd.commit()
        except BaseException:
            lfd.rollback()
            raise
        if logmsg is not None:
            self.log_append(oldbinsha, logmsg)

        return self

    @property
    def reference(self) -> "Reference":
        return self._get_reference()

    @reference.setter
    def reference(self, ref: Union[AnyGitObject, "SymbolicReference", str]) -> "SymbolicReference":
        return self.set_reference(ref)

    ref = reference

    @classmethod
    def to_full_path(cls, path: Union[PathLike, "SymbolicReference"]) -> PathLike:
        """
        :return: Full repository-relative path
        """
        if isinstance(path, SymbolicReference):
            path = path.path
        full_ref_path = path
        if cls._common_path_default and not os.fspath(path).startswith(cls._common_path_default + "/"):
            full_ref_path = f"{cls._common_path_default}/{path}"
        return full_ref_path

    @classmethod
    def delete(cls, repo: "Repo", path: PathLike) -> None:
        """Delete the reference at the given path.

        :param repo: Repository to delete the reference from
        :param path: Short or full path pointing to the reference
        """
        full_ref_path = cls.to_full_path(path)
        abs_path = os.path.join(repo.common_dir, full_ref_path)
        if os.path.exists(abs_path):
            os.remove(abs_path)
        else:
            pack_file_path = cls._get_packed_refs_path(repo)
            try:
                new_lines = []
                with open(pack_file_path, "rb") as reader:
                    for line_bytes in reader:
                        line = line_bytes.decode(defenc)
                        if full_ref_path not in line:
                            new_lines.append(line)
                with open(pack_file_path, "wb") as fd:
                    fd.writelines(line.encode(defenc) for line in new_lines)
            except OSError:
                pass

        reflog_path = RefLog.path(cls(repo, full_ref_path))
        if os.path.isfile(reflog_path):
            os.remove(reflog_path)

    @classmethod
    def _create(
        cls: Type[T_References],
        repo: "Repo",
        path: PathLike,
        resolve: bool,
        reference: Union["SymbolicReference", str],
        force: bool,
        logmsg: Union[str, None] = None,
    ) -> T_References:
        """Internal method to create a new symbolic reference."""
        git_dir = _git_dir(repo, path)
        full_ref_path = cls.to_full_path(path)
        abs_ref_path = os.path.join(git_dir, full_ref_path)

        target = reference
        if resolve:
            target = repo.rev_parse(str(reference))

        if not force and os.path.isfile(abs_ref_path):
            target_data = str(target)
            if isinstance(target, SymbolicReference):
                target_data = os.fspath(target.path)
            if not resolve:
                target_data = "ref: " + target_data
            with open(abs_ref_path, "rb") as fd:
                existing_data = fd.read().decode(defenc).strip()
            if existing_data != target_data:
                raise OSError(
                    f"Reference at {full_ref_path} already exists, pointing to {existing_data}, requested was {target_data}"
                )

        ref = cls(repo, full_ref_path)
        ref.set_reference(target, logmsg)
        return ref

    @classmethod
    def create(
        cls: Type[T_References],
        repo: "Repo",
        path: PathLike,
        reference: Union["SymbolicReference", str] = "HEAD",
        logmsg: Union[str, None] = None,
        force: bool = False,
        **kwargs: Any,
    ) -> T_References:
        """Create a new symbolic reference.

        :param repo: Repository to create the reference in
        :param path: Full path at which the new symbolic reference is supposed to be created
        :param reference: Reference which the new symbolic reference should point to
        :param force: Force creation if the reference already exists
        :param logmsg: Message to append to the reflog or None
        :return: Newly created symbolic reference
