        except Exception as e:
            raise RuntimeError(f"Failed to create symbolic reference at {path}: {e}") from e

    def mock_set_reference(self, ref: Union[AnyGitObject, "SymbolicReference", str], logmsg: Union[str, None] = None) -> "SymbolicReference":
        return self.set_reference(ref, logmsg)

    @classmethod
    def mock_create(cls: Type[T_References], repo: "Repo", path: PathLike, reference: Union["SymbolicReference", str] = "HEAD", logmsg: Union[str, None] = None, force: bool = False) -> T_References:
        return cls.create(repo, path, reference, logmsg, force)

