    @classmethod
    def _iter_packed_refs_with_file(cls, repo: "Repo", file: IO[str]) -> Iterator[Tuple[str, str]]:
        """Return an iterator yielding pairs of sha1/path pairs (as strings) for the
        corresponding refs using a provided file object.

        :param file: A file-like object containing the packed refs data.
        """
